use vstd::prelude::*;

verus! {

    // Function to split lines of strings
    // Args:
    // - a: non-empty vector of Strings
    // - keepends: boolean flag (unused here except carrying through)
    // Returns:
    // - Vec of Vec of Strings,
    // where output.len() == a.len()
    // and each inner Vec<String> is non-empty.
    fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>>
        requires
            a.len() > 0,
        ensures
            |output: &Vec<Vec<String>>| output.len() == a.len() &&
            forall(|i: usize| i < a.len() ==> output.index(i).len() > 0),
    {
        let mut output: Vec<Vec<String>> = Vec::new();

        let mut i: usize = 0;
        while i < a.len()
            invariant
                i <= a.len(),
                output.len() == i,
                forall(|j: usize| j < i ==> output.index(j).len() > 0),
            decreases
                a.len() - i,
        {
            // Construct inner vector by just putting the original string inside
            let inner: Vec<String> = Vec::from_elem(1, a.index(i).clone());

            // inner vector length is 1, so non-empty
            output.push(inner);
            i = i + 1;
        }

        output
    }
}

